//! Single-player UI attack preparation with native hit queries and the ordered
//!43a830 reaction chain. Missing raw context is returned as a typed boundary.
use super::{Game,original_attack_click as click,original_selection as selection,original_orders_game::Event,original_world_contact as world,original_combat};
#[derive(Clone,Debug)]pub(crate) struct Input{pub hardware:bool,pub point:[i16;2],pub fallback_point:[i16;2],pub inside_view:bool,pub cursor_icon:u16,pub override_ground:Option<[i16;2]>,pub repair_records:Option<Vec<click::RepairBuilding>>}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub(crate) enum Boundary{MissingActor,MissingWorld,MissingTerrain,MissingRepair,MissingHardwareRange,MissingSavedClass,MissingSourceIcon,MissingLinkContext,MissingFort}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub(crate) struct Order{pub index:usize,pub event:Event}
#[derive(Clone,Debug)]pub(crate) struct Batch{pub decision:click::Decision,pub orders:Vec<Order>}
fn event(c:selection::Command)->Event{Event::classified(c.opcode,[c.args[0],c.args[1]],c.args[2])}
impl Game{
 pub(crate) fn native_click_grenade_total(&self,index:usize)->Option<u8>{let u=self.units.get(index)?;let member=self.native_group_rosters.members.get(u.native_slot?)?.as_ref()?;let row=self.native_group_rosters.pool.get(usize::from(member.group))?;let mut sum=0i16;for role in 0..21{if let Some(slot)=row.member(role){let u=self.units.iter().rev().find(|u|u.native_slot==Some(usize::from(slot)))?;sum=sum.wrapping_add(i16::from(u.grenades as i8));}}Some(sum as u8)}
 fn native_click_saved_class(&self,index:usize)->Result<u8,Boundary>{let u=self.units.get(index).ok_or(Boundary::MissingActor)?;if original_combat::animation_family(&u.kind)!=32{return Ok(0);}self.native_selection.contexts.get(u.native_slot.ok_or(Boundary::MissingActor)?).and_then(|c|c.saved_class8e).ok_or(Boundary::MissingSavedClass)}
 fn native_click_unit_hit(&self,point:[i16;2],inside_view:bool)->Option<click::UnitHit>{let mut units=vec![click::Selectable{position:[0;2],family:-1,flags31:0,flags8a:0,phase35:0};240];for slot in 0..240{if let Some(u)=self.units.iter().rev().find(|u|u.native_slot==Some(slot)){if let Some(m)=self.native_group_rosters.members[slot].as_ref(){units[slot]=click::Selectable{position:[(u.x/2.).floor()as i16,(u.y/2.).floor()as i16],family:original_combat::animation_family(&u.kind)as i8,flags31:m.flags31,flags8a:m.flags8a,phase35:u.native_phase35};}}}let slot=click::unit_at(&units,point,inside_view)?;let m=self.native_group_rosters.members[slot].as_ref()?;Some(click::UnitHit{slot:slot as u8,group:m.group,role:m.role,flags31:m.flags31})}
 ///The caller supplies any unavailable workshop raw records explicitly. A
 ///repair miss can still be proved when no live repair BUILD can contain X/Y
 ///for any possible signed3a byte; no guessed door offset is substituted.
 pub(crate) fn classify_native_human_attack(&self,index:usize,input:&Input)->Result<click::Decision,Boundary>{
  let u=self.units.get(index).ok_or(Boundary::MissingActor)?;let slot=u.native_slot.ok_or(Boundary::MissingActor)?;let m=self.native_group_rosters.members[slot].as_ref().ok_or(Boundary::MissingActor)?;let family=original_combat::animation_family(&u.kind);let hit=self.native_click_unit_hit(input.point,input.inside_view);let buildings=self.native_world_buildings().ok_or(Boundary::MissingWorld)?;let objects=self.native_world_scan_objects().iter().map(|o|click::Destructible{position:o.position,template_flags18:o.template_flags18}).collect::<Vec<_>>();let unavailable=std::cell::Cell::new(None);
  let grenades=self.native_click_grenade_total(index);if !input.hardware&&hit.is_none()&&grenades.is_none(){return Err(Boundary::MissingActor);}let ci=click::Input{class:u.native_class7c,family,actor_slot:slot as u8,actor_flags31:m.flags31,player:u.team as i8,grenade_total:grenades.unwrap_or(0),click:input.point,fallback_click:input.fallback_point,previous:self.native_order_arguments,cursor_icon:input.cursor_icon,override_ground:input.override_ground};
  let query=|q:click::Query,p:&mut [i16;2]|match q{
   click::Query::Repair=>if let Some(records)=&input.repair_records{click::repair_at(records,*p).map(|(_,at,owner)|{*p=at;owner})}else{match self.native_hardware_repair_at(*p){Ok(Some((at,owner)))=>{*p=at;Some(owner as i8)},Ok(None)=>None,Err(_)=>{unavailable.set(Some(Boundary::MissingRepair));None}}},
   click::Query::Terrain=>{let Some(code)=self.native_selection_terrain_code(*p)else{unavailable.set(Some(Boundary::MissingTerrain));return None;};let saved=match self.native_click_saved_class(index){Ok(c)=>c,Err(e)=>{unavailable.set(Some(e));return None;}};(click::terrain_admission(code,u.native_class7c,family,saved,ci.grenade_total)!=0).then_some(0)},
   click::Query::Building=>world::first_building(&buildings,*p,false,false).map(|(_,at)|{*p=at;0}),
   click::Query::Destructible=>click::destructible_at(&objects,*p).map(|_|0),
   click::Query::OutOfRange=>{let Some(range)=u.native_hardware_slot.and_then(|s|self.native_hardware_pool.get(s)).map(|w|w.attributes.bytes[5])else{unavailable.set(Some(Boundary::MissingHardwareRange));return None;};click::out_of_range([(u.x/2.).floor()as i16,(u.y/2.).floor()as i16],*p,u.native_class7c,family,range).then_some(0)},
  };let d=if input.hardware{click::hardware(ci,hit,query)}else{click::infantry(ci,hit,query)};if let Some(e)=unavailable.get(){return Err(e);}Ok(d)
 }
 ///Classify once, broadcast secondary leaders in43a9f0 order, then finish the
 ///primary with originalXY and the final query-mutated metadata. Context and
 ///mask changes roll back if a raw dependency is unavailable. This prepares
 ///only raw events; the caller owns accepted Web command/path dispatch.
 pub(crate) fn prepare_native_human_attack_batch(&mut self,primary:usize,input:&Input)->Result<Batch,Boundary>{
  let decision=self.classify_native_human_attack(primary,input)?;let Some(original)=decision.event else{return Ok(Batch{decision,orders:vec![]});};let before=self.native_selection.clone();let result=(||{
   if let Some(icon)=decision.icon{self.record_native_selection_icon(primary,icon);}let mut orders=vec![];if !matches!(original.opcode,1|2|3|5){orders.push(Order{index:primary,event:event(original)});return Ok(Batch{decision,orders});}let candidates=self.native_selection_broadcast_candidates(primary).ok_or(Boundary::MissingActor)?;let mut current_source=primary;let mut working=original;
   for index in candidates{let u=self.units.get(index).ok_or(Boundary::MissingActor)?.clone();let slot=u.native_slot.ok_or(Boundary::MissingActor)?;let source=self.units.get(current_source).ok_or(Boundary::MissingActor)?;let source_slot=source.native_slot.ok_or(Boundary::MissingActor)?;let source_context=self.native_selection.contexts[source_slot];let source_family=original_combat::animation_family(&source.kind);let family=original_combat::animation_family(&u.kind);let saved=self.native_click_saved_class(index)?;let grenade_total=self.native_click_grenade_total(index).ok_or(Boundary::MissingActor)?;let ground_code=if working.opcode==5&&working.args[0]==3456&&u.native_class7c==15{self.native_selection_terrain_code([working.args[1],working.args[2]]).ok_or(Boundary::MissingTerrain)?}else{0};let buildings=self.native_world_buildings().ok_or(Boundary::MissingWorld)?;let bridges=self.native_world_bridges().ok_or(Boundary::MissingWorld)?;
    let reaction=selection::broadcast_reaction(selection::ReactionInput{command:working,source_family,source_icon:source_context.icon_a8.ok_or(Boundary::MissingSourceIcon)?,family,class:u.native_class7c,saved_class:saved,grenade_total_low:grenade_total,ground_code},|p|{let bridge=bridges.iter().take(12).any(|&b|world::bridge_contains(b,*p));let building=world::first_building(&buildings,*p,true,false).is_some_and(|(_,at)|{*p=at;true});(bridge,building)},|g|usize::try_from(g).ok().and_then(|s|self.native_group_rosters.pool.get(s)).and_then(|r|r.member(0))).ok_or(Boundary::MissingActor)?;
    working=reaction.outer;if reaction.copy_context{self.native_selection.contexts[slot].link28=Some(source_context.link28.ok_or(Boundary::MissingLinkContext)?);}let command=reaction.recursive.or_else(||(!reaction.handled).then_some(reaction.outer));if let Some(c)=command{let mut e=event(c);if e.opcode==1{let fort=self.native_fort_bases().ok_or(Boundary::MissingFort)?[0];let point=e.waypoint;let near=fort[0]>=point[0]&&fort[0]<=point[0].wrapping_add(160)&&fort[1]>=point[1]&&fort[1]<=point[1].wrapping_add(160);let group=self.native_group_rosters.members[slot].as_ref().ok_or(Boundary::MissingActor)?.group;let changes_source=!near&&self.native_selection.find(group).is_some_and(|f|f.member!=0);e=self.disperse_native_human_move(index,e).ok_or(Boundary::MissingWorld)?;if changes_source{current_source=index;}}orders.push(Order{index,event:e});}if let Some(icon)=reaction.icon{self.record_native_selection_icon(index,icon);}
   }
   let mut primary_command=original;primary_command.args[2]=working.args[2];orders.push(Order{index:primary,event:event(primary_command)});Ok(Batch{decision,orders})
  })();if result.is_err(){self.native_selection=before;}result
 }
}
#[cfg(test)]mod tests{
 use super::*;
 fn field()->Game{let mut g=Game::new(0,1,743);let template=g.buildings.iter().find(|b|b.kind=="fort").unwrap().clone();g.map.original=true;g.map.width=64;g.map.height=64;g.map.terrain_codes=vec![1;4096];g.map.native_terrain_plane=vec![1;16384];g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.native_group_rosters.clear();for(i,kind)in["grunt","jeep","tough"].into_iter().enumerate(){g.spawn(kind,0,100.+i as f64*40.,100.,7+i,None);}for(i,base)in[[800.,32.],[800.,800.]].into_iter().enumerate(){let mut b=template.clone();b.id=500+i;b.team=1-i as i32;b.raw_base=Some((base[0],base[1]));b.x=base[0]*2.;b.y=base[1]*2.;g.buildings.push(b);}g.maintain_native_group_rosters();for i in 0..3{g.initialize_native_selection_context(g.units[i].native_slot.unwrap());}g.import_native_world(&super::super::Value::Null);let groups=(0..3).map(|i|g.native_group_rosters.group_slot(0,g.units[i].squad).unwrap()as u8).collect::<Vec<_>>();g.select_native_groups(&groups);g}
 fn input()->Input{Input{hardware:false,point:[400,500],fallback_point:[400,500],inside_view:true,cursor_icon:0xadf,override_ground:None,repair_records:None}}
 #[test]fn live_ground_attack_broadcast_moves_bullet_units_without_reclassifying_every_actor(){let mut g=field();let prepared=g.prepare_native_human_attack_batch(2,&input()).unwrap();assert_eq!(prepared.orders.iter().map(|o|o.index).collect::<Vec<_>>(),vec![0,1,2]);assert_eq!(prepared.orders[0].event,Event::classified(1,[400,500],2));assert_eq!(prepared.orders[1].event,Event::classified(1,[400,500],2));assert_eq!(prepared.orders[2].event,Event::classified(5,[3456,400],500));assert_eq!(g.native_selection.contexts[g.units[0].native_slot.unwrap()].icon_a8,Some(0xabb));assert_eq!(g.native_selection.contexts[g.units[2].native_slot.unwrap()].icon_a8,Some(0xadf));assert!(g.units.iter().all(|u|u.native_order5c==0));}
 #[test]fn unavailable_saved_class_rolls_back_all_prepared_icons_and_selection_masks(){let mut g=field();g.units[1].kind="apc".into();let slot=g.units[1].native_slot.unwrap();g.native_selection.contexts[slot].saved_class8e=None;let before=g.native_selection.clone();assert_eq!(g.prepare_native_human_attack_batch(2,&input()).unwrap_err(),Boundary::MissingSavedClass);assert_eq!(g.native_selection.contexts,before.contexts);assert_eq!(g.native_selection.rows,before.rows);assert_eq!(g.native_selection.used,before.used);}
 #[test]fn explicit_repair_records_cover_the_special_enemy_door_query_without_guessing_workshop_state(){let mut g=field();let mut b=g.buildings[0].clone();b.id=19;b.kind="repair".into();b.raw_base=None;b.x=800.;b.y=1000.;g.buildings.push(b);g.import_native_world(&super::super::Value::Null);let mut request=input();request.point=[412,510];request.fallback_point=request.point;assert_eq!(g.classify_native_human_attack(2,&request),Err(Boundary::MissingRepair));request.repair_records=Some(vec![click::RepairBuilding{position:[400,500],kind:0,hp:100,remaining:0,offset3a:0,owner:1}]);let d=g.classify_native_human_attack(2,&request).unwrap();assert_eq!(d.event,Some(selection::Command{opcode:5,args:[3456,432,524]}));}
}
